// The agent's configuration (PR-FBX-46, R1-D-178): one JSON file the tenant mounts read-only,
// by default `/etc/infrabyx-tally-agent/config.json` (the path is the program's first argument).
// It holds no secret: the one-time enrolment code is a file in the state directory that the agent
// removes once enrolled, and the key is generated by the agent itself.
//
//   * `platformUrl`: the product's API origin; `https:` only, no user-info, no query.
//   * `tallyUrl`: TallyPrime's XML port (default `http://127.0.0.1:9000`); plain `http:` is the
//     only scheme TallyPrime serves, so it must be a loopback or private address, `localhost` or
//     `host.docker.internal`: the books never cross the internet unencrypted.
//   * `stateDir`: where `agent.json` (the key and identity) lives (default `/data`).
import { readFile } from "node:fs/promises";
import { isIP } from "node:net";
import { z } from "zod";

export const DEFAULT_CONFIG_PATH = "/etc/infrabyx-tally-agent/config.json";

const Config = z
  .object({
    platformUrl: z.string().max(2048),
    tallyUrl: z.string().max(2048).default("http://127.0.0.1:9000"),
    stateDir: z.string().min(1).max(1024).default("/data"),
    /**
     * `auto` (default): on Windows keep the key under DPAPI for the agent's account, else in the
     * 0600 state file; `file`: always the file (reported as a warning at enrolment). #136 (4).
     */
    keyProtection: z.enum(["auto", "file"]).default("auto"),
    /** Windows PowerShell 5.1 for the DPAPI calls (default its standard path). */
    powershellPath: z.string().min(3).max(260).optional(),
    /** Per TallyPrime request, in seconds (default 30). */
    tallyTimeoutSeconds: z.number().int().min(1).max(300).default(30),
  })
  .strict();
export type AgentConfig = z.infer<typeof Config>;

export class ConfigError extends Error {}

function privateOrLoopback(host: string): boolean {
  const h = host.replace(/^\[|\]$/g, "").toLowerCase();
  if (h === "localhost" || h === "host.docker.internal") return true;
  const v = isIP(h);
  if (v === 4) {
    const [a, b] = h.split(".").map(Number) as [number, number];
    return a === 127 || a === 10 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168);
  }
  if (v === 6) return h === "::1" || /^f[cd][0-9a-f]{2}:/.test(h);
  return false;
}

/** Checks a parsed configuration; throws `ConfigError` naming the field. */
export function checkConfig(raw: unknown): AgentConfig {
  const r = Config.safeParse(raw);
  if (!r.success)
    throw new ConfigError(`config: ${r.error.issues[0]?.path.join(".") || "root"} is invalid`);
  const c = r.data;
  let p: URL;
  let t: URL;
  try {
    p = new URL(c.platformUrl);
    t = new URL(c.tallyUrl);
  } catch {
    throw new ConfigError("config: platformUrl and tallyUrl are absolute URLs");
  }
  if (p.protocol !== "https:" || p.username || p.password || p.search || p.hash)
    throw new ConfigError("config: platformUrl is https:, with no user-info, query or fragment");
  if (t.protocol !== "http:" || t.username || t.password || t.search || t.hash)
    throw new ConfigError("config: tallyUrl is TallyPrime's http: port, with no user-info");
  if (!privateOrLoopback(t.hostname))
    throw new ConfigError(
      "config: tallyUrl must be a loopback or private address on the tenant's own network",
    );
  return { ...c, platformUrl: p.origin, tallyUrl: t.origin };
}

export async function loadConfig(path = DEFAULT_CONFIG_PATH): Promise<AgentConfig> {
  let text: string;
  try {
    text = await readFile(path, "utf8");
  } catch {
    throw new ConfigError(`config: cannot read ${path}`);
  }
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    throw new ConfigError("config: not JSON");
  }
  return checkConfig(raw);
}
